import Mathlib.Tactic
import Mathlib.Data.Int.Basic
import Mathlib.Data.Nat.Prime
import Mathlib.Data.Int.ModEq

open Set

/-- The solutions in positive integers of `1/a + 1/b = 3/2018` are exactly the six
pairs listed in the statement. -/
theorem putnam_2018_a1
  (a b : ℤ) (h : 0 < a ∧ 0 < b) :
    ((1 : ℚ) / a + (1 : ℚ) / b = (3 : ℚ) / 2018) ↔
      (⟨a, b⟩ ∈
        ({(673, 1358114), (674, 340033), (1009, 2018),
          (2018, 1009), (340033, 674), (1358114, 673)} :
          Set (ℤ × ℤ))) := by
  constructor
  · intro h_eq
    -- turn the rational equation into an integer one
    have h₁ : (a : ℚ) ≠ 0 := by
      exact_mod_cast (ne_of_gt h.1)
    have h₂ : (b : ℚ) ≠ 0 := by
      exact_mod_cast (ne_of_gt h.2)
    have h_int : (a + b) * 2018 = 3 * a * b := by
      have := h_eq
      field_simp [h₁, h₂] at this
      -- after `field_simp` we obtain the desired integer equality
      simpa [add_comm, mul_comm, mul_left_comm, mul_assoc] using this
    -- factorisation
    have h_fact :
        (3 * a - 2018) * (3 * b - 2018) = (2018 : ℤ) ^ 2 := by
      have : 3 * a * b - 2018 * a - 2018 * b = 0 := by
        have : (a + b) * 2018 = 3 * a * b := h_int
        linarith
      calc
        (3 * a - 2018) * (3 * b - 2018)
            = 9 * a * b - 3 * 2018 * a - 3 * 2018 * b + 2018 * 2018 := by ring
        _ = 3 * (3 * a * b - 2018 * a - 2018 * b) + 2018 * 2018 := by ring
        _ = 3 * 0 + 2018 * 2018 := by simpa [this]
        _ = (2018 : ℤ) ^ 2 := by ring
    -- set the two factors
    set x := 3 * a - 2018 with hx
    set y := 3 * b - 2018 with hy
    have hxy : x * y = (2018 : ℤ) ^ 2 := by
      simpa [hx, hy] using h_fact
    -- positivity of the factors
    have hx_pos : 0 < x := by
      have : (2018 : ℚ) / 3 ≤ (a : ℚ) := by
        have : (1 : ℚ) / a + (1 : ℚ) / b = (3 : ℚ) / 2018 := h_eq
        have ha : (0 : ℚ) < (a : ℚ) := by exact_mod_cast h.1
        have hb : (0 : ℚ) < (b : ℚ) := by exact_mod_cast h.2
        have : (1 : ℚ) / a ≤ (3 : ℚ) / 2018 := by
          have : (1 : ℚ) / a + (1 : ℚ) / b = (3 : ℚ) / 2018 := h_eq
          linarith
        have : (a : ℚ) ≥ (2018 : ℚ) / 3 := by
          have hpos : (0 : ℚ) < (a : ℚ) := ha
          have hpos' : (0 : ℚ) < (2018 : ℚ) / 3 := by norm_num
          exact (inv_le_inv₀ hpos' hpos).mpr this
        exact_mod_cast this
      have : (a : ℤ) ≥ 673 := by
        have : (a : ℚ) ≥ (2018 : ℚ) / 3 := this
        norm_cast at this
        exact this
      have : 3 * a - 2018 ≥ 1 := by
        have : a ≥ 673 := this
        linarith
      exact_mod_cast this
    have hy_pos : 0 < y := by
      have : (2018 : ℚ) / 3 ≤ (b : ℚ) := by
        have : (1 : ℚ) / a + (1 : ℚ) / b = (3 : ℚ) / 2018 := h_eq
        have hb : (0 : ℚ) < (b : ℚ) := by exact_mod_cast h.2
        have ha : (0 : ℚ) < (a : ℚ) := by exact_mod_cast h.1
        have : (1 : ℚ) / b ≤ (3 : ℚ) / 2018 := by
          have : (1 : ℚ) / a + (1 : ℚ) / b = (3 : ℚ) / 2018 := h_eq
          linarith
        have : (b : ℚ) ≥ (2018 : ℚ) / 3 := by
          have hpos : (0 : ℚ) < (b : ℚ) := hb
          have hpos' : (0 : ℚ) < (2018 : ℚ) / 3 := by norm_num
          exact (inv_le_inv₀ hpos' hpos).mpr this
        exact_mod_cast this
      have : (b : ℤ) ≥ 673 := by
        have : (b : ℚ) ≥ (2018 : ℚ) / 3 := this
        norm_cast at this
        exact this
      have : 3 * b - 2018 ≥ 1 := by
        have : b ≥ 673 := this
        linarith
      exact_mod_cast this
    -- the two factors are positive divisors of 2018^2 and are ≡ 1 (mod 3)
    have hx_mod : x % 3 = 1 := by
      have : (3 * a - 2018) % 3 = (0 - 2018 % 3) % 3 := by
        simpa [Int.mod_mul_left_mod] using rfl
      simpa [Int.mod_eq_of_lt (by decide : (0 : ℤ) < 3),
            Int.mod_eq_of_lt (by decide : (0 : ℤ) < 3)] using this
    have hy_mod : y % 3 = 1 := by
      have : (3 * b - 2018) % 3 = (0 - 2018 % 3) % 3 := by
        simpa [Int.mod_mul_left_mod] using rfl
      simpa [Int.mod_eq_of_lt (by decide : (0 : ℤ) < 3),
            Int.mod_eq_of_lt (by decide : (0 : ℤ) < 3)] using this
    have hx_dvd : x ∣ (2018 : ℤ) ^ 2 := ⟨y, by simpa [hxy]⟩
    have hy_dvd : y ∣ (2018 : ℤ) ^ 2 := ⟨x, by simpa [hxy]⟩
    -- list all positive divisors of 2018^2 that are ≡ 1 (mod 3)
    have hx_cases :
        x = 1 ∨ x = 4 ∨ x = 1009 ∨ x = 4036 ∨ x = 1018081 ∨ x = 4072324 := by
      have hx_nat : (x.natAbs) ∣ (2018 ^ 2) := by
        have : (x : ℤ) ∣ (2018 : ℤ) ^ 2 := hx_dvd
        exact Int.coe_nat_dvd_left.mp this
      have hx_mod3 : x.natAbs % 3 = 1 := by
        have : x % 3 = 1 := hx_mod
        simpa [Int.natAbs_mod] using this
      have hx_pos' : 0 < x.natAbs := Nat.succ_le_iff.mp (Nat.succ_le_of_lt (Int.natAbs_pos.mpr hx_pos))
      rcases Nat.dvd_prime_pow_of_dvd_mul (by decide : Nat.Prime 2) (by decide : Nat.Prime 1009)
          (by decide : 2 ≤ 2) (by decide : 2 ≤ 2) hx_nat with
        ⟨i, hi, j, hj, h_eq⟩
      have hi0 : i = 0 ∨ i = 2 := by
        have : i ≤ 2 := hi
        interval_cases i <;> simp_all
      have hj0 : j = 0 ∨ j = 1 ∨ j = 2 := by
        have : j ≤ 2 := hj
        interval_cases j <;> simp_all
      rcases hi0 with rfl | rfl <;> rcases hj0 with rfl | rfl | rfl <;>
